import json

# Invert colors: 0→2, 2 stays 2, 5→0
# rect [0, 2, 0...0, 2] → [2, 2, 2...2, 2] (full line of 2s)
# header [5, 0, 5...5, 0] → [0, 2, 0...0, 2] (rect pattern)

def color_invert(grid):
    output = [[0] * 28 for _ in range(12)]
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 0:
                output[i][j] = 2
            elif val == 2:
                output[i][j] = 2
            elif val == 5:
                output[i][j] = 0
    return output

# Simulate input pattern (I'll make a new one)
